const results = [];
for (const item of $input.all()) {
  const url = item.json.source_url;
  let sourceType = '';
  if (url.includes('youtube.com') || url.includes('youtu.be')) sourceType = 'youtube';
  else if (url.includes('instagram.com/reel') || url.includes('instagram.com/p/')) sourceType = 'instagram';

  if (!sourceType) {
    results.push({ json: { source_url: url, source_type: 'unknown', video_id: '', title: 'ERROR: Unsupported URL', transcript: '', duration_seconds: 0, aspect_ratio: '16:9', video_stream_urls: [] } });
    continue;
  }

  if (sourceType === 'youtube') {
    let vid = '';
    if (url.includes('v=')) vid = url.split('v=')[1].split('&')[0];
    else if (url.includes('youtu.be/')) vid = url.split('youtu.be/')[1].split('?')[0];
    else if (url.includes('/shorts/')) vid = url.split('/shorts/')[1].split('?')[0];
    if (!vid) { results.push({ json: { source_url: url, source_type: 'youtube', video_id: '', title: 'ERROR: Invalid YouTube URL', transcript: '', duration_seconds: 0, aspect_ratio: '16:9', video_stream_urls: [] } }); continue; }

    let title = '';
    try {
      const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://www.youtube.com/oembed?format=json&url=https://www.youtube.com/watch?v=' + vid });
      title = (typeof r === 'string' ? JSON.parse(r) : r).title || '';
    } catch (e) { title = 'Untitled Video'; }

    let transcript = ''; let duration_seconds = 0;
    let videoStreamUrls = [];

    // Try multiple client types to get video stream URLs
    const clients = [
      { clientName: 'ANDROID', clientVersion: '19.09.37' },
      { clientName: 'IOS', clientVersion: '19.09.3' },
      { clientName: 'WEB', clientVersion: '2.20240313.00.00' }
    ];

    for (const client of clients) {
      try {
        const playerResp = await this.helpers.httpRequest({
          method: 'POST',
          url: 'https://www.youtube.com/youtubei/v1/player?prettyPrint=false',
          headers: { 'Content-Type': 'application/json', 'User-Agent': 'Mozilla/5.0' },
          body: JSON.stringify({ videoId: vid, context: { client: { ...client, hl: 'en' } } })
        });
        const pd = typeof playerResp === 'string' ? JSON.parse(playerResp) : playerResp;

        if (!duration_seconds) duration_seconds = parseInt(pd?.videoDetails?.lengthSeconds || '0', 10);

        // Collect ALL available MP4 stream URLs
        const formats = [...(pd?.streamingData?.formats || []), ...(pd?.streamingData?.adaptiveFormats || [])];
        for (const f of formats) {
          if (f.url && f.mimeType && f.mimeType.includes('video/mp4')) {
            videoStreamUrls.push({ url: f.url, itag: f.itag, quality: f.qualityLabel || f.quality || '', width: f.width || 0, height: f.height || 0 });
          }
        }

        // Get transcript from first successful client
        if (!transcript) {
          const tracks = pd?.captions?.playerCaptionsTracklistRenderer?.captionTracks;
          if (tracks && tracks.length > 0) {
            const t = tracks.find(t => t.languageCode === 'en') || tracks[0];
            const caps = await this.helpers.httpRequest({ method: 'GET', url: t.baseUrl + '&fmt=json3' });
            const cd = typeof caps === 'string' ? JSON.parse(caps) : caps;
            transcript = (cd.events || []).filter(e => e.segs).map(e => e.segs.map(s => s.utf8).join('')).join(' ').replace(/\s+/g, ' ').trim();
          }
          if (!transcript) { const desc = pd?.videoDetails?.shortDescription; if (desc && desc.length > 10) transcript = desc; }
        }

        if (videoStreamUrls.length > 0) break; // Got URLs, stop trying other clients
      } catch (e) { /* try next client */ }
    }

    if (!transcript) transcript = 'No transcript available.';

    // Sort: prefer lower resolution (smaller file, faster upload to Gemini)
    videoStreamUrls.sort((a, b) => (a.width || 9999) - (b.width || 9999));

    results.push({ json: { source_url: url, source_type: 'youtube', video_id: vid, title, transcript, duration_seconds, aspect_ratio: url.includes('/shorts/') ? '9:16' : '16:9', video_stream_urls: videoStreamUrls } });
  }

  if (sourceType === 'instagram') {
    const reelMatch = url.match(/instagram\.com\/(?:reel|reels|p)\/([A-Za-z0-9_-]+)/);
    const shortcode = reelMatch ? reelMatch[1] : '';
    if (!shortcode) { results.push({ json: { source_url: url, source_type: 'instagram', video_id: '', title: 'ERROR: Invalid Instagram URL', transcript: '', duration_seconds: 0, aspect_ratio: '9:16', video_stream_urls: [] } }); continue; }
    let title = '';
    try {
      const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://api.instagram.com/oembed/?url=' + encodeURIComponent(url) + '&format=json', headers: { 'User-Agent': 'Mozilla/5.0' } });
      const d = typeof r === 'string' ? JSON.parse(r) : r;
      title = d.title || (d.author_name ? 'Instagram Reel by ' + d.author_name : '');
    } catch (e) {}
    if (!title) title = 'Instagram Reel ' + shortcode;
    results.push({ json: { source_url: url, source_type: 'instagram', video_id: shortcode, title, transcript: title, duration_seconds: 0, aspect_ratio: '9:16', video_stream_urls: [] } });
  }
}
return results;

const GEMINI_KEY = 'YOUR_GEMINI_API_KEY';
const item = $input.first().json;

try {
  let fileUri = '';
  let usedVideo = false;
  let usedThumbnails = false;
  let thumbnailBase64List = [];
  let downloadDebug = [];

  // ==============================
  // STEP 1: Try to download & upload ACTUAL VIDEO to Gemini
  // ==============================
  const streamUrls = item.video_stream_urls || [];

  for (let i = 0; i < Math.min(streamUrls.length, 5); i++) {
    if (usedVideo) break;
    const streamInfo = streamUrls[i];
    try {
      downloadDebug.push('Trying itag=' + streamInfo.itag + ' quality=' + streamInfo.quality);

      const videoResp = await this.helpers.httpRequest({
        method: 'GET',
        url: streamInfo.url,
        encoding: 'arraybuffer',
        returnFullResponse: true,
        timeout: 90000,
        headers: {
          'User-Agent': 'Mozilla/5.0 (Linux; Android 14; Pixel 8) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/121.0.6167.101 Mobile Safari/537.36',
          'Accept': '*/*',
          'Accept-Encoding': 'identity',
          'Range': 'bytes=0-'
        }
      });

      const videoBuffer = Buffer.from(videoResp.body);
      const videoSizeMB = videoBuffer.length / (1024 * 1024);
      downloadDebug.push('Downloaded ' + videoSizeMB.toFixed(1) + 'MB');

      if (videoSizeMB < 0.05) {
        downloadDebug.push('Too small, likely error page');
        continue;
      }
      if (videoSizeMB > 200) {
        downloadDebug.push('Too large, skipping');
        continue;
      }

      // Upload to Gemini File API
      const initResp = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://generativelanguage.googleapis.com/upload/v1beta/files?key=' + GEMINI_KEY,
        headers: {
          'X-Goog-Upload-Protocol': 'resumable',
          'X-Goog-Upload-Command': 'start',
          'X-Goog-Upload-Header-Content-Length': videoBuffer.length.toString(),
          'X-Goog-Upload-Header-Content-Type': 'video/mp4',
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ file: { displayName: 'source_' + Date.now() + '.mp4' } }),
        returnFullResponse: true
      });

      const uploadUrl = initResp.headers['x-goog-upload-url'];
      if (!uploadUrl) { downloadDebug.push('No upload URL from Gemini'); continue; }

      const uploadResp = await this.helpers.httpRequest({
        method: 'POST',
        url: uploadUrl,
        headers: {
          'Content-Length': videoBuffer.length.toString(),
          'X-Goog-Upload-Offset': '0',
          'X-Goog-Upload-Command': 'upload, finalize'
        },
        body: videoBuffer,
        returnFullResponse: true,
        timeout: 240000
      });

      const fileInfo = typeof uploadResp.body === 'string' ? JSON.parse(uploadResp.body) : uploadResp.body;
      let fileName = fileInfo?.file?.name;
      fileUri = fileInfo?.file?.uri || '';
      let fileState = fileInfo?.file?.state || 'PROCESSING';
      downloadDebug.push('Uploaded to Gemini, state=' + fileState);

      // Poll until ACTIVE
      let pollCount = 0;
      while (fileState === 'PROCESSING' && pollCount < 60) {
        await new Promise(r => setTimeout(r, 5000));
        pollCount++;
        const statusResp = await this.helpers.httpRequest({
          method: 'GET',
          url: 'https://generativelanguage.googleapis.com/v1beta/' + fileName + '?key=' + GEMINI_KEY
        });
        const statusData = typeof statusResp === 'string' ? JSON.parse(statusResp) : statusResp;
        fileState = statusData.state;
        fileUri = statusData.uri || fileUri;
      }

      if (fileState === 'ACTIVE' && fileUri) {
        usedVideo = true;
        downloadDebug.push('VIDEO READY - fileUri=' + fileUri);
      } else {
        downloadDebug.push('File not active after polling, state=' + fileState);
        fileUri = '';
      }
    } catch (dlErr) {
      downloadDebug.push('Failed: ' + dlErr.message.substring(0, 100));
    }
  }

  // ==============================
  // STEP 2 FALLBACK: If video failed, grab MULTIPLE thumbnails at different timestamps
  // This gives Gemini actual visual content to analyze instead of just text
  // ==============================
  if (!usedVideo && item.video_id && item.source_type === 'youtube') {
    downloadDebug.push('Video download failed, trying multi-thumbnail fallback');
    const vid = item.video_id;

    // YouTube provides thumbnails at these URLs - grab multiple to show different moments
    const thumbUrls = [
      'https://img.youtube.com/vi/' + vid + '/maxresdefault.jpg',
      'https://img.youtube.com/vi/' + vid + '/sddefault.jpg',
      'https://img.youtube.com/vi/' + vid + '/hqdefault.jpg',
      'https://img.youtube.com/vi/' + vid + '/mqdefault.jpg',
      // Storyboard thumbnails at different points in the video
      'https://img.youtube.com/vi/' + vid + '/1.jpg',
      'https://img.youtube.com/vi/' + vid + '/2.jpg',
      'https://img.youtube.com/vi/' + vid + '/3.jpg'
    ];

    for (const tUrl of thumbUrls) {
      try {
        const thumbResp = await this.helpers.httpRequest({
          method: 'GET',
          url: tUrl,
          encoding: 'arraybuffer',
          returnFullResponse: true,
          timeout: 10000
        });
        const buf = Buffer.from(thumbResp.body);
        // Skip tiny placeholder images (YouTube returns a small grey image for missing thumbnails)
        if (buf.length > 5000) {
          thumbnailBase64List.push(buf.toString('base64'));
        }
      } catch (e) { /* skip */ }
    }

    if (thumbnailBase64List.length > 0) {
      usedThumbnails = true;
      downloadDebug.push('Got ' + thumbnailBase64List.length + ' thumbnails');
    }
  }

  // ==============================
  // STEP 3: Call Gemini to analyze
  // ==============================
  const parts = [];

  if (usedVideo && fileUri) {
    // === BEST CASE: Gemini watches the actual video ===
    parts.push({
      fileData: { mimeType: 'video/mp4', fileUri: fileUri }
    });
    parts.push({
      text: `YOU MUST WATCH THE VIDEO FILE ABOVE. Do NOT rely on the title or transcript — they may be misleading or unrelated to the actual visual content.

Video Title (may be clickbait, IGNORE if it doesn't match what you see): ${item.title || ''}
Video Duration: ${item.duration_seconds || 0} seconds

INSTRUCTIONS:
1. WATCH the video from start to end
2. DESCRIBE ONLY what you actually SEE in the video frames
3. IGNORE the title — if the title says "cooking" but the video shows someone dancing, describe the dancing
4. For each scene, describe: exact appearance of subjects, their clothing, their actions, the environment, camera work, lighting, colors
5. Be extremely specific — "a person with shoulder-length dark wavy hair wearing a loose white linen shirt" not "a person"

Return ONLY valid JSON (no markdown, no fences):
{
  "scene_count": <number>,
  "scenes": [
    {
      "timestamp": "0-5s",
      "subject_appearance": "exact physical description of who/what is visible",
      "clothing_accessories": "exact clothing, jewelry, items",
      "actions": "specific movements, gestures, interactions",
      "setting": "exact environment, background details",
      "camera": "distance, angle, movement",
      "lighting": "source, direction, color temperature, shadows",
      "colors": "dominant colors, grading style",
      "mood": "emotional tone"
    }
  ],
  "overall_style": "complete visual style",
  "consistent_elements": "what stays the same throughout",
  "video_narrative": "what VISUALLY happens from first frame to last frame",
  "title_matches_content": true or false
}`
    });
  } else if (usedThumbnails && thumbnailBase64List.length > 0) {
    // === FALLBACK: Send multiple thumbnail images ===
    // Send up to 5 thumbnails so Gemini can see actual visual content
    const thumbsToSend = thumbnailBase64List.slice(0, 5);
    for (let i = 0; i < thumbsToSend.length; i++) {
      parts.push({
        inlineData: { mimeType: 'image/jpeg', data: thumbsToSend[i] }
      });
    }
    parts.push({
      text: `I've provided ${thumbsToSend.length} images from different moments of a video. LOOK AT EACH IMAGE CAREFULLY.

Video Title (may be misleading — TRUST THE IMAGES, not the title): ${item.title || ''}
Duration: ${item.duration_seconds || 0} seconds
Transcript (secondary context only): ${(item.transcript || '').substring(0, 1500)}

INSTRUCTIONS:
1. ANALYZE EACH IMAGE — describe what you actually see in each one
2. The images show different moments from the same video
3. If the title says one thing but the images show something different, TRUST THE IMAGES
4. Describe: subjects' appearance, clothing, actions, environment, lighting, colors, mood
5. Piece together the visual narrative from these snapshots

Return ONLY valid JSON (no markdown, no fences):
{
  "scene_count": <number based on distinct scenes visible>,
  "scenes": [
    {
      "timestamp": "image 1",
      "subject_appearance": "what you see",
      "clothing_accessories": "what you see",
      "actions": "what you see",
      "setting": "what you see",
      "camera": "what you see",
      "lighting": "what you see",
      "colors": "what you see",
      "mood": "what you see"
    }
  ],
  "overall_style": "visual style across all images",
  "consistent_elements": "what stays the same",
  "video_narrative": "visual story pieced together from the images",
  "title_matches_content": true or false
}`
    });
  } else {
    // === WORST CASE: Text only (no visual content available) ===
    parts.push({
      text: `WARNING: Could not load the video or any thumbnails. Analysis is based ONLY on text.

Video Title: ${item.title || ''}
Duration: ${item.duration_seconds || 0}s
Aspect Ratio: ${item.aspect_ratio || '16:9'}
Transcript: ${item.transcript || ''}

Based on the transcript (NOT the title, which may be clickbait), describe what this video likely shows. Mark everything as inference.

Return ONLY valid JSON:
{
  "scene_count": 3,
  "scenes": [{"timestamp":"inferred","subject_appearance":"inferred","clothing_accessories":"inferred","actions":"inferred","setting":"inferred","camera":"inferred","lighting":"inferred","colors":"inferred","mood":"inferred"}],
  "overall_style": "inferred",
  "consistent_elements": "inferred",
  "video_narrative": "inferred",
  "title_matches_content": "unknown - could not verify"
}`
    });
  }

  const systemText = usedVideo
    ? 'You are a professional video analyst. You are watching an ACTUAL VIDEO FILE. Your #1 rule: describe ONLY what you SEE in the video. The video title and transcript may be completely unrelated to the visual content (clickbait, misleading titles are common). If the title says "How to Cook Pasta" but the video shows a person skateboarding, you MUST describe the skateboarding. NEVER let the title override what your eyes see. Be extremely specific about visual details — colors, clothing, body type, hair, environment, lighting. Output ONLY valid JSON.'
    : usedThumbnails
    ? 'You are a professional video analyst. You are looking at ACTUAL IMAGES captured from different moments of a video. Your #1 rule: describe ONLY what you SEE in these images. The video title may be clickbait or misleading. TRUST THE IMAGES, not the title. If the images show something different from what the title suggests, describe what the images show. Be extremely specific about visual details. Output ONLY valid JSON.'
    : 'You are a professional video analyst. The video and thumbnails could not be loaded. You must infer visual content from the transcript only. Be honest that these are inferences. Output ONLY valid JSON.';

  const body = {
    contents: [{ role: 'user', parts: parts }],
    systemInstruction: { parts: [{ text: systemText }] },
    generationConfig: { temperature: 0.1 }
  };

  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=' + GEMINI_KEY,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
    timeout: 240000
  });

  const resp = typeof response === 'string' ? JSON.parse(response) : response;
  if (resp.error) throw new Error('Gemini API error: ' + JSON.stringify(resp.error));
  if (resp.candidates?.[0]?.finishReason === 'SAFETY') throw new Error('Gemini SAFETY filter blocked this video');

  let analysisText = resp.candidates?.[0]?.content?.parts?.[0]?.text || '';
  if (!analysisText) throw new Error('Empty Gemini response');
  analysisText = analysisText.replace(/[\x00-\x1F\x7F]/g, ' ');

  let analysis;
  try { analysis = JSON.parse(analysisText); } catch (e) {
    const m = analysisText.match(/\{[\s\S]*\}/);
    try { analysis = m ? JSON.parse(m[0]) : { overall_style: analysisText }; } catch (e2) { analysis = { overall_style: analysisText }; }
  }

  const method = usedVideo ? 'VIDEO_UPLOADED' : usedThumbnails ? 'MULTI_THUMBNAIL_FALLBACK' : 'TEXT_ONLY_FALLBACK';

  return [{
    json: {
      source_url: item.source_url,
      title: item.title,
      transcript: item.transcript,
      duration_seconds: item.duration_seconds,
      aspect_ratio: item.aspect_ratio,
      source_type: item.source_type,
      analysis: JSON.stringify(analysis),
      debug_error: '',
      debug_method: method,
      debug_details: downloadDebug.join(' | ')
    }
  }];
} catch (err) {
  return [{
    json: {
      source_url: item.source_url || '',
      title: item.title || '',
      transcript: item.transcript || '',
      duration_seconds: item.duration_seconds || 0,
      aspect_ratio: item.aspect_ratio || '16:9',
      source_type: item.source_type || '',
      analysis: '{}',
      debug_error: 'ANALYZE ERROR: ' + err.message,
      debug_method: 'FAILED',
      debug_details: ''
    }
  }];
}

const GEMINI_KEY = 'YOUR_GEMINI_API_KEY';
const item = $input.first().json;
const transcript = (item.transcript || '').substring(0, 3000);

if (item.debug_error) {
  return [{
    json: {
      source_url: item.source_url || '', video_title: item.title || '', status: 'error',
      segment_1_prompt: '', segment_2_prompt: '', segment_3_prompt: '',
      global_style: '', character_description: '',
      segment_1_video_url: '', segment_2_video_url: '', segment_3_video_url: '',
      combined_video_url: '', completed_at: new Date().toISOString(),
      debug_error: item.debug_error, debug_method: item.debug_method || '', debug_details: item.debug_details || ''
    }
  }];
}

try {
  let analysis = {};
  try { analysis = JSON.parse(item.analysis || '{}'); } catch(e) { analysis = { overall_style: item.analysis }; }

  // Build rich scene context from the visual analysis
  let sceneDetails = '';
  if (analysis.scenes && analysis.scenes.length > 0) {
    sceneDetails = analysis.scenes.map((s, i) => {
      return `SCENE ${i+1} (${s.timestamp || 'unknown'}):\n` +
        `  What is visible: ${s.subject_appearance || s.people || 'unknown'}\n` +
        `  Clothing/items: ${s.clothing_accessories || 'unknown'}\n` +
        `  Actions: ${s.actions || 'unknown'}\n` +
        `  Environment: ${s.setting || 'unknown'}\n` +
        `  Camera work: ${s.camera || 'unknown'}\n` +
        `  Lighting: ${s.lighting || 'unknown'}\n` +
        `  Colors: ${s.colors || 'unknown'}\n` +
        `  Mood: ${s.mood || 'unknown'}`;
    }).join('\n\n');
  }

  const titleMatchWarning = analysis.title_matches_content === false
    ? '\n\nWARNING: The video title does NOT match the actual content. Base your prompts on the SCENE DESCRIPTIONS above, NOT the title.\n'
    : '';

  const userText = `VISUAL ANALYSIS OF THE ORIGINAL VIDEO (from Gemini watching the actual video/images):

${sceneDetails || item.analysis || 'No detailed analysis available'}

OVERALL VISUAL STYLE: ${analysis.overall_style || 'unknown'}
CONSISTENT ELEMENTS ACROSS SCENES: ${analysis.consistent_elements || 'unknown'}
VISUAL NARRATIVE (what happens): ${analysis.video_narrative || 'unknown'}
ASPECT RATIO: ${analysis.aspect_ratio_observed || item.aspect_ratio || '16:9'}
${titleMatchWarning}
Analysis method: ${item.debug_method || 'unknown'} (${item.debug_method === 'VIDEO_UPLOADED' ? 'Gemini watched the actual video' : item.debug_method === 'MULTI_THUMBNAIL_FALLBACK' ? 'Gemini analyzed multiple screenshots' : 'text inference only'})

---

Write exactly 3 video prompts that RECREATE what was seen in the original video. These are 3 sequential segments.

CRITICAL — FAITHFULLY RECREATE THE VISUAL CONTENT:
- Base your prompts on the SCENE DESCRIPTIONS above, which come from Gemini actually watching the video
- Recreate the SAME type of environment (if it shows a kitchen, use a kitchen; if outdoors at sunset, use outdoors at sunset)
- Recreate the SAME type of actions (if cooking, show cooking; if dancing, show dancing)
- Recreate the SAME lighting style (warm, cool, natural, neon, etc.)
- Recreate the SAME color palette (the dominant colors described in the analysis)
- Recreate the SAME mood and energy
- Describe the character similarly to the analysis (hair type, build, clothing style) but keep it GENERIC

SAFETY RULES:
- NEVER describe real people, celebrities, or named individuals
- NEVER mention ethnicity, race, or nationality
- NEVER mention real brand names
- NEVER reference the original video or any platform
- Use generic descriptions: "a person", "a woman", "a man"
- Describe hair style, clothing, build — but keep anonymous

PROMPT FORMAT:
- 60-100 words each
- Plain English describing what the viewer sees
- Include: subject appearance, specific actions, environment, lighting, colors, mood
- NO timestamps, NO technical jargon, NO tag lists at the end
- NO negative words (no, not, without)
- NO text, speech, audio, watermarks

SEGMENTS:
- Segment 1 = Opening (first third of the video narrative)
- Segment 2 = Middle (second third)
- Segment 3 = Conclusion (final third)
- SAME character across all 3, each flows into the next

Return ONLY valid JSON:
{
  "segment_1_prompt": "60-100 words, opening scene faithful to original",
  "segment_2_prompt": "60-100 words, middle scene",
  "segment_3_prompt": "60-100 words, closing scene",
  "global_style": "overall visual style consistent across all 3",
  "character_description": "generic character used in all segments"
}`;

  const body = {
    contents: [{ role: 'user', parts: [{ text: userText }] }],
    systemInstruction: { parts: [{ text: `You write AI video generation prompts that faithfully recreate existing videos. You receive a detailed visual analysis from Gemini which WATCHED the actual video or analyzed its screenshots.

Your job:
1. Read the scene-by-scene analysis carefully — it describes what was ACTUALLY VISIBLE in the video
2. Write 3 prompts that would produce videos looking very similar to the original
3. Match the setting, actions, lighting, colors, and mood from the analysis
4. Keep characters generic for safety, but match their described appearance (hair, build, clothing style)
5. Use concrete visual language — "warm golden light through sheer curtains" not "nice lighting"

The prompts should produce videos that a viewer would recognize as recreating the same content as the original.

Output ONLY valid JSON, no markdown fences.` }] },
    generationConfig: { temperature: 0.3 }
  };

  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=' + GEMINI_KEY,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
    timeout: 120000
  });

  const resp = typeof response === 'string' ? JSON.parse(response) : response;
  if (resp.error) throw new Error('Gemini API error: ' + JSON.stringify(resp.error));
  if (resp.candidates?.[0]?.finishReason === 'SAFETY') throw new Error('SAFETY filter blocked');

  let text = resp.candidates?.[0]?.content?.parts?.[0]?.text || '';
  if (!text) throw new Error('Empty response');
  text = text.replace(/[\x00-\x1F\x7F]/g, ' ');

  let parsed;
  try { parsed = JSON.parse(text); } catch (e) {
    const m = text.match(/\{[\s\S]*\}/);
    try { parsed = m ? JSON.parse(m[0]) : null; } catch (e2) { parsed = null; }
  }

  if (!parsed || !parsed.segment_1_prompt) throw new Error('Parse failed. Raw: ' + text.substring(0, 300));

  return [{
    json: {
      source_url: item.source_url || '', video_title: item.title || '', status: 'prompts_ready',
      segment_1_prompt: parsed.segment_1_prompt || '',
      segment_2_prompt: parsed.segment_2_prompt || '',
